import{d as l,C as r,o as h,c as m,j as i,a,E as e,a3 as u}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"中庸·第18章","description":"《中庸》第 18 章——无忧者其惟文王乎：父作子述；武王缵绪而有天下；周公成文武之德，定追王与葬祭丧服之礼。","frontmatter":{"title":"中庸·第18章","description":"《中庸》第 18 章——无忧者其惟文王乎：父作子述；武王缵绪而有天下；周公成文武之德，定追王与葬祭丧服之礼。","category":"guide","aliases":["第18章","中庸第18章","无忧者其惟文王"],"source":["《礼记》","《四书章句集注》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/zhongyong/chapter-18.md","filePath":"lizhimingde/sishu-wujing/zhongyong/chapter-18.md","lastUpdated":1790316338000}'),d={name:"lizhimingde/sishu-wujing/zhongyong/chapter-18.md"},x=l({...d,setup(p){const o=[{id:"wenwang",label:"无忧者其惟文王乎 · 父作之，子述之",showLabel:!0,sentences:[["子曰：“",{text:"无忧",glossary:"wuyou"},"者其惟文王乎！以",{text:"王季",glossary:"wangji"},"为父，以",{text:"武王",glossary:"wuwang"},"为子，父作之，子述之。"]],note:"孔子说：能没有忧虑的，大概只有文王吧！因为「以王季为父，以武王为子」——父亲王季开创于前，儿子武王绍述于后，「父作之，子述之」，上下两代足以相成，故能无忧。此章以文王为「无忧」之典范。"},{id:"wuwang",label:"武王缵绪 · 壹戎衣而有天下",showLabel:!0,sentences:[["武王",{text:"缵",glossary:"zuan"},{text:"大王",glossary:"taiwang"},"、王季、文王之",{text:"绪",glossary:"xu"},"。",{text:"壹戎衣",glossary:"yirongyi"},"而有天下，身不失天下之",{text:"显名",glossary:"xianming"},"。尊为天子，富有四海之内。宗庙飨之，子孙保之。"]],note:"武王继承太王、王季、文王的统绪（缵＝继），「壹戎衣而有天下」——一次用兵便取得天下（戎衣，一说即大殷），而且「身不失天下之显名」：尊为天子，富有四海，宗庙祭祀之，子孙保守之。"},{id:"zhougong",label:"周公成文武之德 · 追王与葬祭之礼",showLabel:!0,sentences:[["武王",{text:"末受命",glossary:"moshouming"},"，周公成文武之德，",{text:"追王",glossary:"zhuiwang"},"大王、王季，上祀",{text:"先公",glossary:"xiangong"},"以天子之礼。斯礼也，达乎诸侯大夫，及士庶人。父为大夫，子为士；葬以大夫，祭以士。父为士，子为大夫；葬以士，祭以大夫。"],[{text:"期之丧",glossary:"qizhisang"},"达乎大夫，",{text:"三年之丧",glossary:"sannianzhisang"},"达乎天子，父母之丧",{text:"无贵贱一也",glossary:"wuguijian"},"。”"]],note:"武王晚年才受天命，周公完成文王、武王的德业：追尊太王、王季为王（追王），又上祭先公以天子之礼。此礼下及诸侯、大夫以及士、庶人——「父为大夫，子为士，则葬以大夫、祭以士；父为士，子为大夫，则葬以士、祭以大夫」。又：期之丧（一年之丧）达乎大夫，三年之丧达乎天子，而父母的丧礼则无分贵贱。"}],s=[{id:"wuyou",term:"无忧",pinyin:"wú yōu",meaning:"没有忧虑。朱注：「此言文王之事。」父作子述，前后相承，故无忧。"},{id:"wangji",term:"王季",pinyin:"wáng jì",meaning:"文王之父。朱注引《书》「王季其勤王家」，谓其所作亦积功累仁之事。"},{id:"wuwang",term:"武王",pinyin:"wǔ wáng",meaning:"文王之子姬发。"},{id:"zuan",term:"缵",pinyin:"zuǎn",meaning:"继承。缵大王、王季、文王之绪，即继承三代之业。"},{id:"taiwang",term:"大王",pinyin:"tài wáng",meaning:"古公亶父，王季之父。大：读 tài。朱注引《书》「大王肇基王迹」。"},{id:"xu",term:"绪",pinyin:"xù",meaning:"统绪、业。"},{id:"yirongyi",term:"壹戎衣",pinyin:"yī róng yī",meaning:"一著戎衣（甲胄）以伐纣。戎衣：甲胄之属；壹：一、一旦。"},{id:"xianming",term:"显名",pinyin:"xiǎn míng",meaning:"显赫的名声。朱注：「身不失天下之显名。」"},{id:"moshouming",term:"末受命",pinyin:"mò shòu mìng",meaning:"晚年才受天命。朱注：「末，犹老也。」"},{id:"zhuiwang",term:"追王",pinyin:"zhuī wàng",meaning:"追尊为王。王：此处作动词，读 wàng。"},{id:"xiangong",term:"先公",pinyin:"xiān gōng",meaning:"组绀以上至后稷。"},{id:"qizhisang",term:"期之丧",pinyin:"jī zhī sāng",meaning:"一年之丧。期：读 jī。"},{id:"sannianzhisang",term:"三年之丧",pinyin:"sān nián zhī sāng",meaning:"父母之丧，守三年。"},{id:"wuguijian",term:"无贵贱一也",pinyin:"wú guì jiàn yī yě",meaning:"不分贵贱，都是一样。朱注：「推己以及人也。」"}];return(y,n)=>{const g=r("DaoTextReading"),t=r("DaoKeywordCards");return h(),m("div",null,[n[0]||(n[0]=i("h1",{id:"中庸·第18章",tabindex:"-1"},[a("中庸·第18章 "),i("a",{class:"header-anchor",href:"#中庸·第18章","aria-label":'Permalink to "中庸·第18章"'},"​")],-1)),n[1]||(n[1]=i("h2",{id:"【原典层】原文",tabindex:"-1"},[a("【原典层】原文 "),i("a",{class:"header-anchor",href:"#【原典层】原文","aria-label":'Permalink to "【原典层】原文"'},"​")],-1)),n[2]||(n[2]=i("p",null,"第十八章依文王、武王、周公三代展开：文王「无忧」（父作子述）、武王「缵绪」（壹戎衣而有天下）、周公「成德」（追王先公、定葬祭丧服之礼）。默认竹简沉浸通读；切「经典阅读」可点生词。",-1)),e(g,{colophon:"无忧者其惟文王 · 缵绪 · 周公成德",tone:"ink",sections:o,glossary:s,"default-mode":"slips","aria-label":"中庸·第18章 原文"}),n[3]||(n[3]=i("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[a("【原典层】注音与字词 "),i("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),e(t,{items:[{term:"无忧",pinyin:["wú","yōu"],meaning:"没有忧虑。父作子述、前后相承，故无忧。"},{term:"缵",pinyin:["zuǎn"],meaning:"继承。缵大王、王季、文王之绪。"},{term:"壹戎衣",pinyin:["yī","róng","yī"],meaning:"一著戎衣（甲胄）以伐纣。戎衣：甲胄之属。"},{term:"末受命",pinyin:["mò","shòu","mìng"],meaning:"晚年才受天命。朱注：「末，犹老也。」"},{term:"追王",pinyin:["zhuī","wàng"],meaning:"追尊为王。王作动词，读 wàng。"}]}),e(t,{items:[{term:"葬以大夫",pinyin:["zàng","yǐ","dà","fū"],meaning:"丧葬用死者之爵。"},{term:"祭以士",pinyin:["jì","yǐ","shì"],meaning:"祭祀用生者之禄。朱注：「葬用死者之爵，祭用生者之禄。」"},{term:"期之丧",pinyin:["jī","zhī","sāng"],meaning:"一年之丧。期：读 jī。适用于大夫以上。"},{term:"三年之丧",pinyin:["sān","nián","zhī","sāng"],meaning:"父母之丧守三年，适用于天子；而父母之丧不分贵贱，一律相同。"},{term:"无贵贱一也",pinyin:["wú","guì","jiàn","yī","yě"],meaning:"不分贵贱，都是一样。朱注：「推己以及人也。」"}]}),n[4]||(n[4]=u('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【原典层】白话译文" tabindex="-1">【原典层】白话译文 <a class="header-anchor" href="#【原典层】白话译文" aria-label="Permalink to &quot;【原典层】白话译文&quot;">​</a></h2><p><strong>无忧者其惟文王乎</strong>：孔子说：「没有忧虑的，大概只有文王吧！以王季为父，以武王为子，父亲创业，儿子继述。」</p><p><strong>武王缵绪 · 壹戎衣而有天下</strong>：武王继承大王、王季、文王的统绪，一著戎衣便取得天下，自身不失天下的显名。尊为天子，富有四海之内。宗庙祭祀他，子孙保有他的基业。</p><p><strong>周公成文武之德 · 追王与葬祭之礼</strong>：武王晚年才受天命；周公成就文王、武王的德业，追尊大王、王季为王，又用天子之礼上祀先公。这礼制，通到诸侯、大夫，以及士、庶人：父为大夫、子为士，葬用大夫之礼、祭用士之礼；父为士、子为大夫，葬用士之礼、祭用大夫之礼。一年之丧通到大夫，三年之丧通到天子，而父母之丧，不论贵贱都是一样的。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>第十八章是一段「三代相承」的叙事：</p><ul><li><strong>文王</strong>：父作子述，故「无忧」</li><li><strong>武王</strong>：缵三代之绪，「壹戎衣而有天下」，身不失显名</li><li><strong>周公</strong>：成文武之德，追王先公，并把礼制推到诸侯、大夫、士、庶人——<strong>葬以死者之爵，祭以生者之禄</strong>；丧服则「父母之丧，无贵贱一也」</li></ul><p>从「德」到「礼」，这一章把前几章的德讲成了可依循的度。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>「无忧」的根据在于「承」</strong>：文王之忧不在己身，而在事业能否接续；父作子述，所以无忧。这三代之间的接力，是本章的骨。</li><li><strong>它把「德」落到「礼」上</strong>：追王、祭祀、葬祭、丧服，都是德的具体形态。朱注特别点出「葬用死者之爵，祭用生者之禄」——礼不是尊卑的炫耀，而是<strong>身份的恰当对应</strong>。</li><li><strong>「父母之丧，无贵贱一也」是全章的暖处</strong>：在层层有别的礼制里，唯这一条上下相同。朱注说这是「推己以及人也」——礼的尽头仍是恕道。</li><li><strong>它与第 17 章连成一线</strong>：舜（孝与德）—文王（作述）—武王（缵绪）—周公（成德制礼），全篇从个人之德，逐渐走向天下之礼。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>看「接力」</strong>：我这一代是「作」还是「述」？上一代留下什么，我又准备留下什么。</li><li><strong>礼是分寸，不是排场</strong>：同一件事，对不同身份的人有不同的恰当做法。</li><li><strong>记住那句「无贵贱一也」</strong>：规则可以有别，但在最要紧处，人是一样的。</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>孔子说：没有忧虑的人，大概只有文王吧——父亲创业，儿子继述，他处在中间，承前启后。</p><p>武王接着三代的统绪，一著戎衣便得了天下，功名不失；周公则成就了文王武王的德业：<strong>追尊先王、厘定祭祀与丧服之礼</strong>，而且这套礼一直通到诸侯、大夫、士与庶人。</p><p>最动人的一句在最后：层层有别的礼制里，<strong>「父母之丧，无贵贱一也」</strong>——在最要紧的地方，人人一样。</p><p>从天子的德，到百姓的礼，这一章把「中」落成了一套可以照着做的分寸。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「父作之，子述之」——我这一代是「作」，还是「述」？</li><li>「父母之丧，无贵贱一也」——层层有别的礼制里，为什么这一条最动人？</li><li>从「德」落到「礼」——把心里的东西变成可依循的制度，难在哪？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-17">中庸·第17章</a>　下章：<a href="/Dao/lizhimingde/sishu-wujing/zhongyong/chapter-19">中庸·第19章</a></li><li>参考：《礼记》第三十一篇；朱熹《四书章句集注·中庸章句》</li></ul>',25))])}}});export{c as __pageData,x as default};
